UPDATE sys_file SET biz_type = 'CRM_PORTAL_TICKET', biz_id = #{ticketId}
WHERE tenant_id = #{identity.tenantId} AND file_id = #{fileId} AND portal_owner_id = #{identity.portalUserId}
    AND biz_type = 'PORTAL_TICKET_UPLOAD' AND access_type = 'PRIVATE' AND deleted = 0
